import { expect, test, uniqueName } from "../../fixtures";

test("the same vendor name is allowed in a different tenant", { tag: "@VEN-04" }, async ({ apiAs }) => {
  // Given a vendor named "Acme Freight" exists in tenant "Globex Procurement"
  const name = uniqueName("Acme Freight");
  const globex = await apiAs("otherTenant");
  const setup = await globex.post("/api/vendors", {
    data: { name, category: "logistics", contact_email: "ops@acmefreight.example" },
  });
  expect(setup.status(), await setup.text()).toBe(201);

  // When I create a vendor named "Acme Freight" in category "logistics" with contact "ops@acmefreight.example"
  const northwind = await apiAs("member");
  const res = await northwind.post("/api/vendors", {
    data: { name, category: "logistics", contact_email: "ops@acmefreight.example" },
  });

  // Then the response status is 201
  expect(res.status(), await res.text()).toBe(201);
  const body = await res.json();
  expect(body.name, JSON.stringify(body)).toBe(name);
  expect(body.category, JSON.stringify(body)).toBe("logistics");
});
